    18	    async fn get_funders_by_text_search_score(
    19	        &self,
    20	        req: &EntitySearchRequest,
    21	    ) -> Result<Vec<(Funder, SearchSimilarity)>, FunderRepoError> {
    22	        sqlx::query!(
    23	            "
    24	            SELECT  
    25	                f.funder_name as name,
    26	                f.funder_kind as kind,
    27	                f.company_number,
    28	                word_similarity($1, f.funder_name) as similarity_score,
    29	                row_number() OVER (ORDER BY word_similarity($1, f.funder_name) DESC) as rank
    30	            FROM funders f
    31	            WHERE word_similarity($1, f.funder_name) >= $2
    32	            ORDER BY similarity_score DESC
    33	            ",
    34	            req.term(),
    35	            req.strictness(),
    36	        )
    37	        .fetch_all(self.pool())
    38	        .await
    39	        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?
    40	        .into_iter()
    41	        .take_while(|r| {
    42	            r.rank.unwrap_or_else(|| i64::from(req.max_entries() + 1))
    43	                <= i64::from(req.max_entries())
    44	        })
    45	        .map(|r| {
    46	            let kind = r.kind.map_or(FunderKind::NotSpecified, |ref kind| {
    47	                FunderKind::from_str(kind).unwrap()
    48	            });
    49	            let funder = Funder::new(r.name, kind);
    50	            let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
    51	            Ok((funder, score))
    52	        })
    53	        .collect()
    54	    }
    55	}
